with with_windows as (select *, lead(shipping_fee) over (partition by customer_id, status order by order_date, id) as next_shipping_fee, lag(shipping_fee) over (partition by customer_id, status order by order_date, id) as prev_shipping_fee, lag(amount) over (partition by customer_id, status order by order_date, id) as prev_amount, row_number() over (partition by customer_id, status order by order_date, id) as event_seq, rank() over (order by shipping_fee desc nulls last) as shipping_fee_rank from orders) select s.id, s.store_id, s.order_date, s.status, s.channel, s.amount, s.discount, s.shipping_fee, s.prev_amount, (select avg(x.revenue) from store_sales x where x.store_id = s.store_id) as avg_store_sale_revenue from with_windows s order by store_id nulls last;
